import sys
from collections import defaultdict

def is_balanced(seq):
    stack = []
    for num in seq:
        if num > 0:
            stack.append(num)
        else:
            if stack and stack[-1] == -num:
                stack.pop()
            else:
                return False
    return not stack

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    cards = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    front_degree = defaultdict(int)
    back_degree = defaultdict(int)
    front_graph = defaultdict(list)
    back_graph = defaultdict(list)

    for u, v in cards:
        front_degree[u] += 1
        back_degree[v] += 1
        front_graph[-u].append(v)
        back_graph[-v].append(u)

    def find_eulerian_path(graph, degree, start):
        path = []
        stack = [start]
        while stack:
            u = stack[-1]
            if graph[u]:
                v = graph[u].pop()
                degree[v] -= 1
                stack.append(v)
            else:
                path.append(stack.pop())
        return path[::-1]

    front_path = find_eulerian_path(front_graph, front_degree, 1)
    back_path = find_eulerian_path(back_graph, back_degree, 1)

    if len(front_path) != 2*n + 1 or len(back_path) != 2*n + 1:
        print("NO")
        return

    front_path = front_path[:-1]
    back_path = back_path[:-1]

    card_order = []
    used = set()
    for i in range(2*n):
        for u, v in cards:
            if u == front_path[i] and v == back_path[i] and (u, v) not in used:
                card_order.append((u, v))
                used.add((u, v))

    if len(card_order) != 2*n:
        print("NO")
        return

    print("YES")
    for u, v in card_order:
        print(u, v)

main()
